python
def fixedPanelsEvenKeyCensus(readings, k):
    a=readings
    out=[]
    s=0
    for i,x in enumerate(a):
        s+=x
        if i>=k: s-=a[i-k]
        if i>=k-1: out.append(s)
    return sum(x%2==0 for x in out)


java
class Solution {
  public int fixedPanelsEvenKeyCensus(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int s=0;for(int i=0;i<a.length;i++){s+=a[i];if(i>=k)s-=a[i-k];if(i>=k-1)out.add(s);}}
    int answer=0;for(int x:out)if(x%2==0)answer++;return answer;
  }
}
